import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const textures = [];
  const materials = [];
  const geometries = [];

  // Load brushed metal roughness map
  const roughnessMap = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  textures.push(roughnessMap);

  // Create procedural scratch normal map for imperfection pass
  const scratchCanvas = document.createElement('canvas');
  scratchCanvas.width = 256;
  scratchCanvas.height = 256;
  const scratchCtx = scratchCanvas.getContext('2d');
  scratchCtx.fillStyle = '#8080ff';
  scratchCtx.fillRect(0, 0, scratchCanvas.width, scratchCanvas.height);

  // Add directional scratch patterns
  for (let i = 0; i < 80; i++) {
    const x = Math.random() * scratchCanvas.width;
    const y = Math.random() * scratchCanvas.height;
    const length = Math.random() * 60 + 10;
    const angle = Math.random() * Math.PI * 2;

    scratchCtx.strokeStyle = `rgba(127, 127, 200, ${0.08 + Math.random() * 0.12})`;
    scratchCtx.lineWidth = 0.5 + Math.random();
    scratchCtx.beginPath();
    scratchCtx.moveTo(x, y);
    scratchCtx.lineTo(x + Math.cos(angle) * length, y + Math.sin(angle) * length);
    scratchCtx.stroke();
  }

  const scratchNormalMap = new THREE.CanvasTexture(scratchCanvas);
  textures.push(scratchNormalMap);

  // Torus knot geometry
  const knotGeom = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36);
  geometries.push(knotGeom);

  // Brushed metal PBR material with anisotropy and imperfection
  const knotMaterial = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#cacfd5'),
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    roughnessMap: roughnessMap,
    normalMap: scratchNormalMap,
    normalScale: new THREE.Vector2(0.15, 0.15),
    anisotropy: 0.9,
  });
  materials.push(knotMaterial);

  const knotMesh = new THREE.Mesh(knotGeom, knotMaterial);
  knotMesh.position.set(0, 0.4, 0);
  knotMesh.castShadow = true;
  knotMesh.receiveShadow = true;
  group.add(knotMesh);

  // Pedestal cylinder (radius 1.1, height 0.5, top at y=-0.35, center at y=-0.6)
  const pedestalGeom = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 64);
  geometries.push(pedestalGeom);

  const pedestalMaterial = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#14141a'),
    roughness: 0.7,
    metalness: 0.35,
  });
  materials.push(pedestalMaterial);

  const pedestalMesh = new THREE.Mesh(pedestalGeom, pedestalMaterial);
  pedestalMesh.position.y = -0.6;
  pedestalMesh.castShadow = true;
  pedestalMesh.receiveShadow = true;
  group.add(pedestalMesh);

  // Contact shadow with radial gradient (radius 1.5, center opacity 0.6 → 0)
  const shadowGeom = new THREE.PlaneGeometry(3, 3, 64, 64);
  geometries.push(shadowGeom);

  const shadowCanvas = document.createElement('canvas');
  shadowCanvas.width = 256;
  shadowCanvas.height = 256;
  const shadowCtx2d = shadowCanvas.getContext('2d');

  const shadowGrad = shadowCtx2d.createRadialGradient(128, 128, 0, 128, 128, 150);
  shadowGrad.addColorStop(0, 'rgba(0, 0, 0, 0.6)');
  shadowGrad.addColorStop(0.65, 'rgba(0, 0, 0, 0.15)');
  shadowGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
  shadowCtx2d.fillStyle = shadowGrad;
  shadowCtx2d.fillRect(0, 0, shadowCanvas.width, shadowCanvas.height);

  const shadowTexture = new THREE.CanvasTexture(shadowCanvas);
  textures.push(shadowTexture);

  const shadowMaterial = new THREE.MeshBasicMaterial({
    map: shadowTexture,
    transparent: true,
    depthWrite: false,
  });
  materials.push(shadowMaterial);

  const shadowMesh = new THREE.Mesh(shadowGeom, shadowMaterial);
  shadowMesh.position.set(0, -0.36, 0.01);
  shadowMesh.rotation.x = -Math.PI / 2;
  group.add(shadowMesh);

  // Backdrop plane with vertical gradient stops
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  geometries.push(backdropGeom);

  const backdropCanvas = document.createElement('canvas');
  backdropCanvas.width = 512;
  backdropCanvas.height = 384;
  const backdropCtx2d = backdropCanvas.getContext('2d');

  const backdropGrad = backdropCtx2d.createLinearGradient(0, 0, 0, backdropCanvas.height);
  backdropGrad.addColorStop(0, '#0b0b10');
  backdropGrad.addColorStop(0.7, '#101017');
  backdropGrad.addColorStop(1, '#16161d');
  backdropCtx2d.fillStyle = backdropGrad;
  backdropCtx2d.fillRect(0, 0, backdropCanvas.width, backdropCanvas.height);

  const backdropTexture = new THREE.CanvasTexture(backdropCanvas);
  textures.push(backdropTexture);

  const backdropMaterial = new THREE.MeshBasicMaterial({
    map: backdropTexture,
  });
  materials.push(backdropMaterial);

  const backdropMesh = new THREE.Mesh(backdropGeom, backdropMaterial);
  backdropMesh.position.z = -3;
  group.add(backdropMesh);

  // Studio lighting setup
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.5, 2.5, 2);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.width = 2048;
  keyLight.shadow.mapSize.height = 2048;
  group.add(keyLight);

  const fillLight = new THREE.DirectionalLight(0xb0b8d8, 0.5);
  fillLight.position.set(-1.5, 1, -1.5);
  group.add(fillLight);

  const ambientLight = new THREE.AmbientLight(0x5a5a7a, 0.4);
  group.add(ambientLight);

  // Text content via fontAtlas
  const headlineLayout = ctx.fontAtlas.layout('Material study 03', {
    family: 'Lora',
    size: 68,
    weight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });

  const headlineMesh = ctx.fontAtlas.createMesh(headlineLayout);
  headlineMesh.position.set(0, -0.8, 0.2);
  group.add(headlineMesh);

  const captionLayout = ctx.fontAtlas.layout('GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', {
    family: 'JetBrains Mono',
    size: 18,
    weight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#ff2a38',
  });

  const captionMesh = ctx.fontAtlas.createMesh(captionLayout);
  captionMesh.position.set(0, -1.2, 0.2);
  group.add(captionMesh);

  // Apply orbit cinematic primitive on load
  if (ctx.primitives && ctx.primitives.orbit) {
    ctx.primitives.orbit(knotMesh, { speed: 0.1, radius: 0.4 });
  }

  // Cleanup function
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    textures.forEach(tex => tex.dispose());
    materials.forEach(mat => mat.dispose());
    geometries.forEach(geom => geom.dispose());
  };

  group.userData.handlers = {};

  return group;
}
